async function visitLedger(stream, visitor) {
  const decoder = new TextDecoder("utf-8");
  const reader = stream.getReader();

  let accepted = 0;
  let rejected = 0;
  let line = 0;
  let pending = "";
  let mustCancel = true;

  async function processLine(text) {
    line += 1;
    if (text.trim() === "") return true;

    let value;
    try {
      value = JSON.parse(text);
    } catch {
      rejected += 1;
      return true;
    }

    accepted += 1;
    return (await visitor({ line, value })) !== false;
  }

  try {
    while (true) {
      const { done, value } = await reader.read();
      if (done) mustCancel = false;

      const text = done
        ? decoder.decode()
        : decoder.decode(value, { stream: true });

      let start = 0;
      let end;

      while ((end = text.indexOf("\n", start)) !== -1) {
        const row = pending + text.slice(start, end);
        pending = "";
        start = end + 1;

        if (!(await processLine(row))) {
          return { accepted, rejected, stopped: true };
        }
      }

      pending += text.slice(start);

      if (done) {
        if (pending.length > 0 && !(await processLine(pending))) {
          return { accepted, rejected, stopped: true };
        }

        return { accepted, rejected, stopped: false };
      }
    }
  } catch (error) {
    mustCancel = true;
    throw error;
  } finally {
    if (mustCancel) await reader.cancel();
    reader.releaseLock();
  }
}
